def comps(g, val):
    R,C=len(g),len(g[0]); seen=set(); out=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]==val and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); size=0
                while stack:
                    x,y=stack.pop(); size+=1
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<R and 0<=b<C and g[a][b]==val and (a,b) not in seen:
                            seen.add((a,b)); stack.append((a,b))
                out.append(size)
    return sorted(out, reverse=True)
